      L("car −1 < 1/2 < 1,  lim (1/2)^{n+1} = 0", "vert", "condition", r=("condition", "la condition sur la raison")),
      L("lim S_n = 1/(1 − 1/2) = 2", "jaune", "limite", cadre="jaune"),
